def seed_item_types(apps, schema_editor):
    MedicineTypeMap = apps.get_model('config', 'MedicineTypeMap')
    SystemSetting = apps.get_model('config', 'SystemSetting')
    if MedicineTypeMap.objects.exists():
        return
    excluded = {'60'}
    setting = SystemSetting.objects.filter(key='analytics_excluded_medicine_types').first()
    if setting and setting.value:
        excluded |= {c.strip() for c in setting.value.split(',') if c.strip()}
    MedicineTypeMap.objects.bulk_create([
        MedicineTypeMap(code=code, group=group, is_medicine=is_med,
                        excluded_from_planning=code in excluded)
        for code, group, is_med in SEED
    ])


